const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0 && r.timestamp);
const today = DateTime.now().setZone('Asia/Kolkata').toFormat('yyyy-LL-dd');
const todays = rows.filter(r => String(r.timestamp).slice(0, 10) === today);

const count = (out) => todays.filter(r => r.outcome === out).length;
const booked = count('booked');
const rescheduled = count('rescheduled');
const cancelled = count('cancelled');
const questions = count('question_answered');
const availChecks = count('availability_checked');
const total = todays.length;

// Busiest service among bookings
const svcCounts = {};
todays.filter(r => r.outcome === 'booked' && r.service).forEach(r => { svcCounts[r.service] = (svcCounts[r.service] || 0) + 1; });
let busiest = '—';
let max = 0;
for (const k in svcCounts) { if (svcCounts[k] > max) { max = svcCounts[k]; busiest = k; } }

const dateLabel = DateTime.now().setZone('Asia/Kolkata').toFormat('cccc, LLLL d, yyyy');

let text;
if (total === 0) {
  text = '\uD83D\uDCCA *Glow MedSpa — Daily Summary (' + dateLabel + ')*\nNo voice activity recorded today.';
} else {
  text = '\uD83D\uDCCA *Glow MedSpa — Daily Summary (' + dateLabel + ')*\n' +
    '\u2022 Total actions handled: ' + total + '\n' +
    '\uD83D\uDFE2 Appointments booked: ' + booked + '\n' +
    '\uD83D\uDD04 Rescheduled: ' + rescheduled + '\n' +
    '\uD83D\uDD34 Cancelled: ' + cancelled + '\n' +
    '\u2139\uFE0F Availability checks: ' + availChecks + '\n' +
    '\u2753 Questions answered: ' + questions + '\n' +
    '\u2B50 Busiest service: ' + busiest;
}

return [{ json: { summaryText: text, total: total } }];
